// Reject anything that does not carry the shared secret. n8n webhooks are
// public URLs; without this check anyone could forge a 'venue.paid'.
const expected = $env.SB_WEBHOOK_SECRET;
const got = $input.first().json.headers?.['x-webhook-secret'];
if (!expected || got !== expected) {
  throw new Error('unauthorized webhook call');
}
const body = $input.first().json.body ?? {};
return [{ json: body }];

// One WhatsApp line per event type. Kept as plain text on purpose —
// this is a notification to one person, not a marketing asset.
const v = $input.first().json;
const money = (c) => c ? '\u20ac' + (c / 100).toFixed(2) : '';
const text = {
  'venue.provisioned': `\u2705 NEW VENUE LIVE\n${v.venue} (${v.city || ''} ${v.country})\n${v.competition}\nCode: ${v.invite_code}\n${v.join_url}`,
  'venue.paid': `\ud83d\udcb0 PAID \u2014 ${money(v.amount)} ${(v.currency||'').toUpperCase()}`,
  'venue.payment_failed': `\u26a0\ufe0f PAYMENT FAILED\n${v.venue} (${v.email})\nAttempt ${v.attempt}`,
  'venue.churned': `\ud83d\udd34 CHURNED\nvenue ${v.venue_id}`,
  'venue.trial_will_end': `\u23f3 TRIAL ENDS IN 3 DAYS\n${v.venue} (${v.email})`,
}[v.event] || `SuperBrain venue event: ${v.event}`;
return [{ json: { to: '__WHATSAPP_TO__', text, raw: v } }];

// Zoho customer + invoice payload. Only built for a real provisioning
// event; the amount comes from Stripe, never recomputed here.
const v = $input.first().json;
return [{ json: {
  contact_name: v.venue,
  company_name: v.venue,
  email: v.email,
  phone: v.phone || '',
  billing_address: { city: v.city || '', country: v.country || '' },
  custom_fields: [
    { label: 'Venue ID', value: v.venue_id },
    { label: 'League', value: v.competition },
    { label: 'Stripe customer', value: v.stripe_customer_id },
  ],
} }];

// Social proof post. Names the venue and city only \u2014 never the owner,
// never the amount paid.
const v = $input.first().json;
const where = v.city ? `${v.city}, ${v.country}` : v.country;
return [{ json: {
  text: `${v.venue} in ${where} just launched their own ${v.competition} prediction league. Their regulars are picking this weekend's scores now. \u26bd`,
  link: v.join_url,
} }];
